package com.ethk3.novaonepro.strategyv2;
import java.util.*;
import java.nio.charset.StandardCharsets;
/** Display projection only. The complete machine frame is already serialized in the original measure. */
public final class ResearchFrameBoundR30R1 {
 private ResearchFrameBoundR30R1(){}public static final int MAX_BYTES=262144;
 static String clip(String s,int max){if(s.length()<=max)return s;int n=max;if(n>0&&Character.isHighSurrogate(s.charAt(n-1)))n--;return s.substring(0,n)+"…[显示省略，完整原件见同run research_measure]";}
 @SuppressWarnings("unchecked") public static Map<String,Object> project(Map<String,Object> original){
  for(int detailLimit:new int[]{256,128,64,32}){
   Map<String,Object> f=new LinkedHashMap<>();for(String key:Arrays.asList("viewId","datasetHash","role","researchOnly","qualityEffective","status","reason","fromOrdinal","throughOrdinal","windowScope","runId","machineMeasure","computationNs","componentPath","mean","lower95","upper95","evaluatedIssues","proposalId")){Object v=original.get(key);if(original.containsKey(key))f.put(key,v instanceof String?clip((String)v,512):v);}
   for(String key:Arrays.asList("matrixRows","matrixColumns","series"))if(original.get(key) instanceof List){List<Object> names=new ArrayList<>();if(((List<?>)original.get(key)).size()>120)throw new IllegalStateException("RESEARCH_FRAME_AXIS_PAGINATION_REQUIRED");for(Object v:(List<?>)original.get(key))names.add(clip(String.valueOf(v),64));f.put(key,names);}
   List<Object> rows=new ArrayList<>();Object raw=original.get("points");List<?> points=raw instanceof List?(List<?>)raw:Collections.emptyList();if(points.size()>120)throw new IllegalStateException("RESEARCH_FRAME_POINT_PAGINATION_REQUIRED");int clipped=0;for(Object o:points){Map<?,?> p=(Map<?,?>)o;Map<String,Object> row=new LinkedHashMap<>();for(String key:Arrays.asList("label","value","lower","upper","n","details","open","expected","stack")){Object v=p.get(key);if(v instanceof String){String bounded=clip((String)v,key.equals("details")?detailLimit:128);if(!bounded.equals(v))clipped++;v=bounded;}if(key.equals("stack")&&v instanceof List&&((List<?>)v).size()>12)throw new IllegalStateException("RESEARCH_FRAME_SERIES_PAGINATION_REQUIRED");if(p.containsKey(key))row.put(key,v);}rows.add(row);}f.put("points",rows);
   List<Object> edges=new ArrayList<>();if(original.get("edges") instanceof List){if(((List<?>)original.get("edges")).size()>180)throw new IllegalStateException("RESEARCH_FRAME_EDGE_PAGINATION_REQUIRED");for(Object o:(List<?>)original.get("edges")){Map<?,?> e=(Map<?,?>)o;Map<String,Object> edge=new LinkedHashMap<>();for(String key:Arrays.asList("from","to","label"))edge.put(key,clip(String.valueOf(e.get(key)),128));edges.add(edge);}}f.put("edges",edges);
   if(original.get("modelReplayPerformance") instanceof Map){Map<String,Object> summary=new LinkedHashMap<>();for(Map.Entry<?,?> e:((Map<?,?>)original.get("modelReplayPerformance")).entrySet())if(e.getValue()==null||e.getValue() instanceof Number||e.getValue() instanceof Boolean||e.getValue() instanceof String)summary.put(String.valueOf(e.getKey()),e.getValue());summary.put("fullFixedBlocks","ORIGINAL_MEASURE_FRAME:modelReplayPerformance.blocks");f.put("modelReplayPerformance",summary);}
   f.put("displayOriginalPoints",points.size());f.put("displayOmittedPoints",0);f.put("displayDetailsClipped",clipped);f.put("fullMachineFrameSha256",original.get("originalMachineFrameSha256") instanceof String?original.get("originalMachineFrameSha256"):StatsR27.sha256(JsonR27.write(original)));f.put("fullMachineFrameReference","r30r1_research_measure(run_id="+original.get("runId")+").payload_json.frame; graph cache is not an optimization source");f.put("displayScope","BOUNDED_PROJECTION; complete source records, tensor data and block estimates retained in the same original machine measure");if(JsonR27.write(f).getBytes(StandardCharsets.UTF_8).length<=MAX_BYTES)return f;
  }throw new IllegalStateException("RESEARCH_FRAME_BYTE_BUDGET_REQUIRES_PAGINATION");
 }
}
